export function mapApiError(error: unknown, status = 500): Response {
  const message =
    typeof error === "string"
      ? error
      : error instanceof Error
        ? error.message
        : "Unexpected API route error";

  return Response.json(
    {
      message,
      details: error,
    },
    { status }
  );
}

/**
 * Helper for proxy route handlers to forward requests to the backend API
 * with server-side token injection. Use this in app/api/* routes.
 *
 * Example:
 *   export async function GET(request: Request) {
 *     return createAuthProxyHandler(async (client) => {
 *       return UsersService.usersMeRetrieve({ client });
 *     });
 *   }
 */
export async function createAuthProxyHandler(
  handler: (client: Client) => Promise<{
    data?: unknown;
    error?: unknown;
    response?: Response;
  }>
): Promise<Response> {
  try {
    const client = await createAuthedApiClient();
    const result = await handler(client);

    if (result.error) {
      return Response.json(
        { message: "API error", error: result.error },
        { status: result.response?.status ?? 400 }
      );
    }

    return Response.json(result.data, { status: 200 });
  } catch (error) {
    return mapApiError(error);
  }
}

import { AUTH_STORAGE_KEY } from "@/lib/auth-session";
import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { UserProfile, PatchedUserProfileRequest } from "@/api";
import { createClient as createSupabaseBrowserClient } from "@/lib/supabase/client";

interface AuthResponse {
  access_token: string;
  user?: UserProfile;
}

function toErrorMessage(error: unknown) {
  return error instanceof Error ? error.message : String(error);
}

type AuthStore = {
  auth: AuthResponse | null;
  user: UserProfile | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  hasHydrated: boolean;
  error: string | null;
  login: (credentials: { email: string; password: string }) => Promise<AuthResponse>;
  register: (credentials: { email: string; password: string }) => Promise<void>;
  fetchProfile: () => Promise<UserProfile>;
  updateProfile: (payload: PatchedUserProfileRequest) => Promise<void>;
  logout: () => void;
  clearError: () => void;
  setHasHydrated: (value: boolean) => void;
};

export const useAuthStore = create<AuthStore>()(
  persist(
    (set) => ({
      auth: null,
      user: null,
      token: null,
      isAuthenticated: false,
      isLoading: false,
      hasHydrated: false,
      error: null,
      async login(credentials) {
        set({ isLoading: true, error: null });
        try {
          const supabase = createSupabaseBrowserClient();
          const { data, error } = await supabase.auth.signInWithPassword(
            credentials
          );

          if (error) {
            const message = error.message || 'Login failed';
            set({ isLoading: false, error: message, isAuthenticated: false });
            return Promise.reject(new Error(message));
          }

          const session = data.session ?? null;
          const token = session?.access_token ?? null;

          const auth = { access_token: token, user: data.user ?? null } as AuthResponse;

          set({
            auth,
            token,
            isAuthenticated: Boolean(token),
            isLoading: false,
            error: null,
          });

          if (token) localStorage.setItem('auth_token', token);
          return auth;
        } catch (error) {
          set({
            isLoading: false,
            isAuthenticated: false,
            error: toErrorMessage(error),
          });
          return Promise.reject(error instanceof Error ? error : new Error(toErrorMessage(error)));
        }
      },
      async register(payload) {
        set({ isLoading: true, error: null });
        try {
          const supabase = createSupabaseBrowserClient();
          const { data, error } = await supabase.auth.signUp({
            email: payload.email,
            password: payload.password,
            options: { data: payload },
          });

          if (error) {
            const message = error.message || 'Registration failed';
            set({ isLoading: false, error: message });
            return Promise.reject(new Error(message));
          }

          // If signUp returns a session, store token similarly to login
          const session = data.session ?? null;
          const token = session?.access_token ?? null;
          if (token) localStorage.setItem('auth_token', token);

          set({ isLoading: false, error: null });
        } catch (error) {
          set({ isLoading: false, error: toErrorMessage(error) });
          return Promise.reject(error instanceof Error ? error : new Error(toErrorMessage(error)));
        }
      },
      async fetchProfile() {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch("/api/user");
          if (!response.ok) {
            throw new Error(`Failed to fetch profile: ${response.statusText}`);
          }
          const profile = (await response.json()) as UserProfile;
          set({ user: profile, isLoading: false, error: null });
          return profile;
        } catch (error) {
          set({ isLoading: false, error: toErrorMessage(error) });
          return Promise.reject(error instanceof Error ? error : new Error(toErrorMessage(error)));
        }
      },
      async updateProfile(payload) {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch("/api/user", {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
          });
          if (!response.ok) {
            throw new Error(`Failed to update profile: ${response.statusText}`);
          }

          set({ isLoading: false, error: null });
        } catch (error) {
          set({ isLoading: false, error: toErrorMessage(error) });
          return Promise.reject(error instanceof Error ? error : new Error(toErrorMessage(error)));
        }
      },
      logout() {
        localStorage.removeItem("auth_token");
        set({
          auth: null,
          user: null,
          token: null,
          isAuthenticated: false,
          error: null,
        });
      },
      clearError() {
        set({ error: null });
      },
      setHasHydrated(value) {
        set({ hasHydrated: value });
      },
    }),
    {
      name: AUTH_STORAGE_KEY,
      partialize: (state) => ({
        auth: state.auth,
        user: state.user,
        token: state.token,
        isAuthenticated: state.isAuthenticated,
      }),
      onRehydrateStorage: () => (state) => {
        const token = state?.token ?? null;
        if (token) {
          localStorage.setItem("auth_token", token);
        }
        state?.setHasHydrated(true);
      },
    }
  )
);

